<?php
declare(strict_types=1);
require_once __DIR__.'/finance.php';
function finance_stripe_request(string $structure,string $path,array $params=[],string $idempotency=''): array {
    $c=finance_settings($structure);if(!finance_checkout_ready($c))fail(503,'Compte de paiement de cette troupe non raccordé.');$secret=$c['stripe_secret'];if(!is_string($secret)||!preg_match('/^(sk|rk)_(test|live)_/D',$secret))fail(503,'Configuration de paiement invalide.');if(!function_exists('curl_init'))fail(503,'Le serveur doit disposer de cURL.');
    if(!preg_match('~^checkout/sessions(?:/cs_[a-zA-Z0-9_]+)?$~D',$path))fail(500,'Opération de paiement inconnue.');
    $ch=curl_init('https://api.stripe.com/v1/'.$path);$headers=['Authorization: Bearer '.$secret];if($idempotency!=='')$headers[]='Idempotency-Key: '.$idempotency;
    curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_TIMEOUT=>20,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_HTTPHEADER=>$headers,CURLOPT_PROTOCOLS=>CURLPROTO_HTTPS]);if($params)curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>http_build_query($params)]);$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);if(!is_string($raw)||strlen($raw)>1000000||$code<200||$code>=300)fail(502,'Le prestataire ne peut pas traiter le paiement. Réessayez après vérification de son tableau de bord.');try{$r=json_decode($raw,true,32,JSON_THROW_ON_ERROR);}catch(Throwable){fail(502,'Réponse du prestataire illisible.');}if(!is_array($r))fail(502,'Réponse du prestataire invalide.');return $r;
}
function finance_checkout(string $structure,string $actor,string $invoiceId): array {
    membership($structure,$actor,true);$c=finance_settings($structure);if(!finance_checkout_ready($c))fail(503,'Compte de paiement de cette troupe non raccordé.');$pdo=db();$pdo->beginTransaction();$attempt=null;
    try{finance_lock($structure);$invoice=finance_find($structure,$invoiceId);if($invoice['kind']!=='invoice')fail(422,'Choisissez une facture.');$prior=query("SELECT * FROM atelier_checkouts WHERE structure_id=? AND invoice_id=? AND status IN ('creating','open') ORDER BY created_at DESC LIMIT 1",[$structure,$invoiceId])->fetch();
        if($prior){$pdo->commit();if($prior['status']==='open'&&$prior['session_id']){$session=finance_stripe_request($structure,'checkout/sessions/'.$prior['session_id']);if(($session['status']??'')==='open'&&($session['payment_status']??'')!=='paid'&&$prior['url'])return ['url'=>$prior['url']];if(($session['status']??'')==='expired'){query("UPDATE atelier_checkouts SET status='expired' WHERE id=? AND structure_id=?",[$prior['id'],$structure]);return finance_checkout($structure,$actor,$invoiceId);}fail(409,'Paiement en cours de confirmation. Le retour du prestataire mettra le solde à jour.');}fail(409,'Création précédente à réconcilier avec le prestataire avant un nouvel essai.');}
        $balance=finance_balance($structure,$invoice);if(!$balance['due'])fail(422,'Cette facture n’a plus de solde à encaisser.');$attempt=['id'=>uid(),'amount'=>$balance['due'],'expires'=>time()+3600];query('INSERT INTO atelier_checkouts(id,structure_id,invoice_id,amount,status,created_at,expires_at) VALUES(?,?,?,?,?,?,?)',[$attempt['id'],$structure,$invoiceId,$attempt['amount'],'creating',time(),$attempt['expires']]);$pdo->commit();
    }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
    // The amount and the merchant secret come exclusively from this troupe's server records.
    $params=['mode'=>'payment','client_reference_id'=>$invoiceId,'success_url'=>config()['origin'].'/#finances','cancel_url'=>config()['origin'].'/#finances','expires_at'=>$attempt['expires'],'metadata'=>['atelier_attempt'=>$attempt['id']],'line_items'=>[['price_data'=>['currency'=>'eur','unit_amount'=>$attempt['amount'],'product_data'=>['name'=>$invoice['number']]],'quantity'=>1]],'payment_method_types'=>['card']];
    if(($c['allow_sepa']??false)===true)$params['payment_method_types'][]='sepa_debit';
    // A timeout keeps the reservation in "creating". Reconcile with the idempotency key rather than risk a second charge.
    $r=finance_stripe_request($structure,'checkout/sessions',$params,'atelier-'.$attempt['id']);$url=$r['url']??'';$parts=is_string($url)?parse_url($url):false;
    if(!is_string($r['id']??null)||!preg_match('/^cs_[a-zA-Z0-9_]+$/D',$r['id'])||!$parts||($parts['scheme']??'')!=='https'||($parts['host']??'')!=='checkout.stripe.com'||isset($parts['user'])||isset($parts['pass'])||($r['amount_total']??null)!==$attempt['amount']||($r['currency']??'')!=='eur')fail(502,'Réponse de paiement à réconcilier avec le prestataire.');
    query("UPDATE atelier_checkouts SET status='open',session_id=?,url=? WHERE id=? AND structure_id=?",[$r['id'],$url,$attempt['id'],$structure]);audit($structure,$actor,'checkout.created');return ['url'=>$url];
}
function finance_verify_signature(string $raw,string $header,string $secret,int $now): void {
    $timestamp=null;$signatures=[];foreach(explode(',',$header) as $part){[$key,$value]=array_pad(explode('=',trim($part),2),2,'');if($key==='t'&&ctype_digit($value))$timestamp=(int)$value;if($key==='v1')$signatures[]=$value;}
    if(!$secret||$timestamp===null||abs($now-$timestamp)>300)fail(400,'Signature expirée ou absente.');$expected=hash_hmac('sha256',$timestamp.'.'.$raw,$secret);foreach($signatures as $signature)if(hash_equals($expected,$signature))return;fail(400,'Signature invalide.');
}
function finance_stripe_event(string $structure,string $raw,string $signature): array {
    $c=finance_settings($structure);if(!finance_checkout_ready($c))fail(503,'Paiement non configuré.');finance_verify_signature($raw,$signature,$c['stripe_webhook_secret'],time());try{$event=json_decode($raw,true,32,JSON_THROW_ON_ERROR);}catch(Throwable){fail(400,'Événement invalide.');}
    $type=$event['type']??'';if(!in_array($type,['checkout.session.completed','checkout.session.async_payment_succeeded','checkout.session.expired','checkout.session.async_payment_failed'],true))return ['received'=>true];$s=$event['data']['object']??null;if(!is_array($s))fail(400,'Session manquante.');$id=$s['metadata']['atelier_attempt']??'';if(!is_string($id)||!preg_match('/^[a-f0-9]{32}$/D',$id))fail(400,'Référence manquante.');$live=str_contains($c['stripe_secret'],'_live_');if(($event['livemode']??null)!==$live)fail(400,'Mode de paiement incompatible.');
    $pdo=db();$pdo->beginTransaction();try{finance_lock($structure);$a=query('SELECT * FROM atelier_checkouts WHERE id=? AND structure_id=?',[$id,$structure])->fetch();if(!$a)fail(400,'Session inconnue de cette troupe.');if(($s['client_reference_id']??'')!==$a['invoice_id']||($s['amount_total']??null)!==(int)$a['amount']||($s['currency']??'')!=='eur'||!is_string($s['id']??null)||!preg_match('/^cs_[a-zA-Z0-9_]+$/D',$s['id'])||($a['session_id']&&$s['id']!==$a['session_id']))fail(400,'Session incohérente.');
        if($type==='checkout.session.expired'||$type==='checkout.session.async_payment_failed'){if($a['status']!=='paid')query('UPDATE atelier_checkouts SET status=?,session_id=? WHERE id=? AND structure_id=?',[$type==='checkout.session.expired'?'expired':'failed',$s['id'],$id,$structure]);$pdo->commit();return ['received'=>true];}
        if(($s['payment_status']??'')!=='paid'){$pdo->commit();return ['received'=>true];}
        $prior=query('SELECT id FROM atelier_payments WHERE structure_id=? AND provider_ref=?',[$structure,'stripe:'.$s['id']])->fetch();if(!$prior){$created=$event['created']??time();if(!is_int($created))fail(400,'Date d’événement invalide.');$date=(new DateTimeImmutable('@'.$created))->setTimezone(new DateTimeZone('Europe/Paris'))->format('Y-m-d');$row=['id'=>uid(),'invoiceId'=>$a['invoice_id'],'direction'=>'receipt','method'=>'online','amountCents'=>(int)$a['amount'],'date'=>$date,'reference'=>$s['id'],'origin'=>'stripe'];finance_store_payment($structure,$row,'stripe:'.$s['id']);}
        query("UPDATE atelier_checkouts SET status='paid',session_id=? WHERE id=? AND structure_id=?",[$s['id'],$id,$structure]);$pdo->commit();return ['received'=>true];
    }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
